#include <bits/stdc++.h>
using namespace std;
long long rev(long long x){ long long r=0; while(x>0){ r=r*10+x%10; x/=10; } return r; }
int main(){
    int n; cin >> n;
    while(n--){
        long long p; cin >> p;
        int iter=0;
        while (p != rev(p)) { p = p + rev(p); iter++; }
        cout << iter << " " << p << "\n";
    }
}
